// currency (USD or EUR) and locale (en-US or nl-NL).
package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Refactoring log:
//  1. Replaced the hand-rolled selection sort (built from boolean-to-int
//     lookup maps) with sort.Slice and a plain comparator on
//     (date, description, change).
//  2. Removed the goroutine/channel fan-out that formatted rows in
//     "parallel". Rows are formatted sequentially, which is simpler and
//     deterministic, and no longer leaks goroutines when an entry errors.
//  3. Replaced the recursive dummy-entry call used to validate the currency
//     when the input is empty with up-front validation of both the currency
//     and the locale.
//  4. Collapsed the duplicated locale-specific formatting (header, date
//     layout, number separators, sign style) into a single locale value.
//  5. Extracted the currency symbol lookup into a currency value.
//  6. Extracted the repeated digit-grouping code into groupThousands.
//  7. Made description truncation rune-aware so multi-byte characters are
//     not split mid-rune.
//  8. Replaced the empty error messages with descriptive ones.

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders entries as a formatted ledger table for the given
// currency and locale. Entries are ordered by date, then description, then
// change. The input slice is not modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	c, err := newCurrency(currency)
	if err != nil {
		return "", err
	}
	l, err := newLocale(locale)
	if err != nil {
		return "", err
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		return less(sorted[i], sorted[j])
	})

	var b strings.Builder
	b.WriteString(l.header())
	for _, e := range sorted {
		row, err := l.formatRow(c, e)
		if err != nil {
			return "", err
		}
		b.WriteString(row)
	}
	return b.String(), nil
}

// less reports whether entry a sorts before entry b: by date, then
// description, then change.
func less(a, b Entry) bool {
	if a.Date != b.Date {
		return a.Date < b.Date
	}
	if a.Description != b.Description {
		return a.Description < b.Description
	}
	return a.Change < b.Change
}

// currency is a supported currency and its symbol.
type currency struct {
	symbol string
}

func newCurrency(s string) (currency, error) {
	switch s {
	case "USD":
		return currency{symbol: "$"}, nil
	case "EUR":
		return currency{symbol: "€"}, nil
	}
	return currency{}, errors.New("unsupported currency: " + s)
}

// locale holds the formatting rules for one locale.
type locale struct {
	name         string
	dateHeader   string
	descHeader   string
	changeHeader string
	formatDate   func(day, month, year string) string
	thousandsSep byte
	decimalSep   byte
	symbolGap    string // space between the symbol and the amount, if any
	negPrefix    string // prefix for negative amounts, e.g. "("
	negSuffix    string // suffix for negative amounts, e.g. ")" or "-"
}

var (
	enUS = locale{
		name:         "en-US",
		dateHeader:   "Date",
		descHeader:   "Description",
		changeHeader: "Change",
		formatDate:   func(day, month, year string) string { return month + "/" + day + "/" + year },
		thousandsSep: ',',
		decimalSep:   '.',
		symbolGap:    "",
		negPrefix:    "(",
		negSuffix:    ")",
	}
	nlNL = locale{
		name:         "nl-NL",
		dateHeader:   "Datum",
		descHeader:   "Omschrijving",
		changeHeader: "Verandering",
		formatDate:   func(day, month, year string) string { return day + "-" + month + "-" + year },
		thousandsSep: '.',
		decimalSep:   ',',
		symbolGap:    " ",
		negPrefix:    "",
		negSuffix:    "-",
	}
)

func newLocale(s string) (locale, error) {
	switch s {
	case "en-US":
		return enUS, nil
	case "nl-NL":
		return nlNL, nil
	}
	return locale{}, errors.New("unsupported locale: " + s)
}

// header renders the table header row.
func (l locale) header() string {
	return pad(l.dateHeader, 10) + " | " + pad(l.descHeader, 25) + " | " + l.changeHeader + "\n"
}

// formatRow renders a single entry row.
func (l locale) formatRow(c currency, e Entry) (string, error) {
	day, month, year, err := parseDate(e.Date)
	if err != nil {
		return "", err
	}
	return l.formatDate(day, month, year) + " | " +
		formatDescription(e.Description) + " | " +
		rightPad(l.formatAmount(c, e.Change), 13) + "\n", nil
}

// formatAmount renders a change in cents with the locale's separators and
// sign style, e.g. "$1,234.56 " / "($1,234.56)" (en-US) or
// "$ 1.234,56 " / "$ 123,45-" (nl-NL).
func (l locale) formatAmount(c currency, cents int) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	intPart := groupThousands(strconv.Itoa(cents/100), l.thousandsSep)
	amount := intPart + string(l.decimalSep) + fmt.Sprintf("%02d", cents%100)
	if negative {
		return l.negPrefix + c.symbol + l.symbolGap + amount + l.negSuffix
	}
	return c.symbol + l.symbolGap + amount + " "
}

// parseDate validates an ISO "YYYY-MM-DD" date and returns its parts.
func parseDate(s string) (day, month, year string, err error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return "", "", "", errors.New("invalid date: " + s)
	}
	return s[8:10], s[5:7], s[0:4], nil
}

// formatDescription truncates descriptions longer than 25 characters and
// pads the rest to a width of 25.
func formatDescription(d string) string {
	r := []rune(d)
	if len(r) > 25 {
		return string(r[:22]) + "..."
	}
	return string(r) + strings.Repeat(" ", 25-len(r))
}

// groupThousands inserts sep between every group of three digits, counted
// from the right.
func groupThousands(s string, sep byte) string {
	if len(s) <= 3 {
		return s
	}
	rem := len(s) % 3
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if i > 0 && (i-rem)%3 == 0 {
			b.WriteByte(sep)
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// pad left-justifies s in a field of the given width.
func pad(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

// rightPad right-justifies s (measured in runes) in a field of the given
// width.
func rightPad(s string, width int) string {
	r := []rune(s)
	if len(r) >= width {
		return s
	}
	return strings.Repeat(" ", width-len(r)) + s
}
